// Normalized accessors and helper functions
export function normalizeLanguageCode(code: string): string {
  return normalizeCode(code);
}

export function hasLanguage(code: string): boolean {
  const key = normalizeCode(code);
  return Object.prototype.hasOwnProperty.call(LANGUAGES, key);
}

export function getLanguage(code: string): Language | undefined {
  if (!code) return undefined;
  const key = normalizeCode(code);
  return LANGUAGES[key];
}

export function getAllLanguages(): Language[] {
  return Object.values(LANGUAGES);
}

export function getLanguagesByRegion(region: string): Language[] {
  if (!region) return [];
  const q = region.trim().toLowerCase();
  return Object.values(LANGUAGES).filter(lang =>
    lang.region
      .toLowerCase()
      .split(/[,;/|]/)
      .map(s => s.trim())
      .some(r => r === q)
  );
}

export function getCompleteLanguages(): Language[] {
  return Object.values(LANGUAGES).filter(lang => lang.status === 'complete');
}

export function getRTLLanguages(): Language[] {
  return Object.values(LANGUAGES).filter(lang => lang.isRTL);
}

export function getLanguagesByScript(script: string): Language[] {
  if (!script) return [];
  const q = script.trim().toLowerCase();
  return Object.values(LANGUAGES).filter(lang =>
    lang.nativeScript
      .toLowerCase()
      .split(/[ ,/]+/)
      .map(s => s.trim())
      .some(s => s === q)
  );
}

// Stats computed on demand to avoid stale snapshots
export function getLanguageStats() {
  const langs = Object.values(LANGUAGES);
  const totalLanguages = langs.length;
  const totalSpeakers = langs.reduce((sum, l) => sum + (l.totalSpeakers || 0), 0);
  const totalHymns = langs.reduce((sum, l) => sum + (l.hymnsCount || 0), 0);
  const totalPsalms = langs.reduce((sum, l) => sum + (l.psalmsCount || 0), 0);
  const totalWorshipSongs = langs.reduce((sum, l) => sum + (l.worshipSongsCount || 0), 0);
  const completedLanguages = langs.filter(l => l.status === 'complete').length;
  const rtlLanguages = langs.filter(l => l.isRTL).length;
  return {
    totalLanguages,
    totalSpeakers,
    totalHymns,
    totalPsalms,
    totalWorshipSongs,
    completedLanguages,
    rtlLanguages,
  };
}

// Convenience constants (snapshots)
export const LANGUAGE_COUNT = Object.keys(LANGUAGES).length;
export const LANGUAGE_STATS = getLanguageStats();
